#!/usr/bin/env python3
"""Archive existing log/XML records for console-selected failed Bazel targets."""

import argparse
import hashlib
import json
import os
import stat
import subprocess
import sys
import tempfile
from pathlib import Path


def target_path(label: str) -> Path:
    if not label.startswith("//") or "\\" in label:
        raise ValueError("expected a canonical //package:target label")
    package, separator, name = label[2:].partition(":")
    parts = (package.split("/") if package else []) + name.split("/")
    if not separator or any(
        part in ("", ".", "..")
        or ":" in part
        or any(ord(character) < 32 or ord(character) == 127 for character in part)
        for part in parts
    ):
        raise ValueError("unsafe or non-canonical target path")
    return Path(*parts)


def collect(testlogs: Path, output: Path, targets: list[str]) -> tuple[Path, bool]:
    archive_root = output / "failed-test-logs"
    archive_root.mkdir(parents=True, exist_ok=True)
    archive = Path(tempfile.mkdtemp(prefix="invocation-", dir=archive_root))
    manifest = {
        "schema": "bazel_failed_test_logs_v1",
        "scope": (
            "Existing test.log/test.xml and test_attempts log/XML files under "
            "console-selected failed targets only; not a complete suite inventory."
        ),
        "selected_targets": targets,
        "source": {},
        "files": [],
        "errors": [],
    }

    def record_error(target: str | None, path: str, error: Exception) -> None:
        manifest["errors"].append(
            {
                "target": target,
                "path": path,
                "error": f"{type(error).__name__}: {error}",
            }
        )

    try:
        revision = subprocess.run(
            ["git", "rev-parse", "HEAD", "HEAD^{tree}"],
            check=True,
            capture_output=True,
            text=True,
            timeout=10,
        ).stdout.splitlines()
        dirty = subprocess.run(
            ["git", "diff", "--quiet", "HEAD", "--"],
            check=False,
            capture_output=True,
            timeout=10,
        )
        if len(revision) != 2 or dirty.returncode not in (0, 1):
            raise ValueError("could not identify the checked-out Git source")
        manifest["source"] = {
            "commit": revision[0],
            "tree": revision[1],
            "tracked_worktree_dirty": dirty.returncode == 1,
        }
    except (OSError, ValueError, subprocess.SubprocessError) as error:
        record_error(None, "git source", error)

    # Bazel's top-level bazel-testlogs entry may itself be a symlink.
    try:
        root = testlogs.resolve(strict=True)
        if not root.is_dir():
            raise ValueError("testlogs root is not a directory")
    except (OSError, ValueError, RuntimeError) as error:
        record_error(None, "testlogs root", error)
        root = None

    if root is not None:
        for index, target in enumerate(targets):
            previous_count = len(manifest["files"])
            try:
                relative_target = target_path(target)
                directory = root / relative_target
                resolved = directory.resolve(strict=True)
                if not resolved.is_relative_to(root):
                    raise ValueError("target directory escapes the testlogs root")
                if not resolved.is_dir():
                    raise ValueError("target path is not a directory")

                def walk_error(error: OSError) -> None:
                    record_error(target, str(relative_target), error)

                for current, directories, filenames in os.walk(
                    directory, followlinks=False, onerror=walk_error
                ):
                    directories.sort()
                    current_path = Path(current)
                    for name in list(directories):
                        child = current_path / name
                        relative = child.relative_to(root)
                        if name in (
                            "test.outputs",
                            "test.outputs_manifest",
                        ) or name.endswith(".runfiles"):
                            directories.remove(name)
                            continue
                        try:
                            if not child.resolve(strict=True).is_relative_to(root):
                                raise ValueError("directory escapes the testlogs root")
                            if child.is_symlink() or getattr(
                                child.lstat(), "st_reparse_tag", 0
                            ):
                                raise ValueError(
                                    "nested linked directory is not traversed"
                                )
                        except (OSError, ValueError, RuntimeError) as error:
                            directories.remove(name)
                            record_error(target, relative.as_posix(), error)

                    for name in sorted(filenames):
                        source = current_path / name
                        target_relative = source.relative_to(directory)
                        if name not in ("test.log", "test.xml") and not (
                            "test_attempts" in target_relative.parts
                            and source.suffix in (".log", ".xml")
                        ):
                            continue
                        relative = source.relative_to(root)
                        destination = (
                            archive / "targets" / f"{index:04d}" / target_relative
                        )
                        try:
                            resolved = source.resolve(strict=True)
                            if not resolved.is_relative_to(root):
                                raise ValueError("file escapes the testlogs root")
                            if not stat.S_ISREG(resolved.stat().st_mode):
                                raise ValueError("log is not a regular file")
                            destination.parent.mkdir(parents=True, exist_ok=True)
                            digest = hashlib.sha256()
                            size = 0
                            with (
                                resolved.open("rb") as reader,
                                destination.open("xb") as writer,
                            ):
                                before = os.fstat(reader.fileno())
                                while chunk := reader.read(1024 * 1024):
                                    writer.write(chunk)
                                    digest.update(chunk)
                                    size += len(chunk)
                                after = os.fstat(reader.fileno())
                            if (
                                size != before.st_size
                                or before.st_size != after.st_size
                                or before.st_mtime_ns != after.st_mtime_ns
                            ):
                                raise ValueError(
                                    "source log changed while being archived"
                                )
                            manifest["files"].append(
                                {
                                    "target": target,
                                    "testlogs_relative_path": relative.as_posix(),
                                    "archive_relative_path": destination.relative_to(
                                        archive
                                    ).as_posix(),
                                    "bytes": size,
                                    "sha256": digest.hexdigest(),
                                }
                            )
                        except (OSError, ValueError, RuntimeError) as error:
                            try:
                                destination.unlink(missing_ok=True)
                            except OSError as cleanup_error:
                                record_error(target, relative.as_posix(), cleanup_error)
                            record_error(target, relative.as_posix(), error)
                if len(manifest["files"]) == previous_count:
                    raise ValueError(
                        "no existing test log/XML records found for target"
                    )
            except (OSError, ValueError, RuntimeError) as error:
                record_error(target, target, error)

    manifest["complete_for_selected_targets"] = not manifest["errors"]
    (archive / "manifest.json").write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    return archive, manifest["complete_for_selected_targets"]


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--testlogs-dir", required=True, type=Path)
    parser.add_argument("--output-dir", required=True, type=Path)
    args = parser.parse_args()
    targets = list(
        dict.fromkeys(line.rstrip("\r\n") for line in sys.stdin if line.strip())
    )
    try:
        archive, complete = collect(args.testlogs_dir, args.output_dir, targets)
    except (OSError, ValueError, RuntimeError) as error:
        print(f"Failed-test-log archive could not be written: {error}", file=sys.stderr)
        return 1
    print(
        f"Failed-test-log archive: {archive} (complete_for_selected_targets={complete})"
    )
    return 0 if complete else 1


if __name__ == "__main__":
    raise SystemExit(main())

"""Fetch the two immutable PR histories without fetching unrelated repository refs."""

import argparse
import base64
import json
import os
import re
import subprocess


def git(*args):
    return subprocess.check_output(
        ["git", "--no-replace-objects", *args], text=True
    ).strip()


def fetch_history(base, source, repository, token):
    for name, value in (("base", base), ("source", source)):
        if re.fullmatch(r"[0-9a-f]{40}", value or "") is None:
            raise ValueError(f"{name} must be an immutable full commit SHA")
    before = {
        "head": git("rev-parse", "HEAD"),
        "tree": git("rev-parse", "HEAD^{tree}"),
        "status": git("status", "--porcelain", "--untracked-files=normal"),
    }
    if before["head"] != source or before["status"]:
        raise ValueError("history fetch requires the clean exact source checkout")
    shallow_before = git("rev-parse", "--is-shallow-repository") == "true"
    fetch_env = os.environ.copy()
    fetch_env.pop("HEPTA_UI_CHECKOUT_TOKEN", None)
    # Auth is scoped to this one HTTPS fetch and never written into repository
    # configuration. Do not inherit optional Git tracing into an authenticated fetch.
    for key in list(fetch_env):
        if key.startswith("GIT_TRACE") or key == "GIT_CURL_VERBOSE":
            fetch_env.pop(key)
    command = ["git", "--no-replace-objects"]
    if token:
        if re.fullmatch(r"[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+", repository or "") is None:
            raise ValueError("authenticated history fetch requires the repository name")
        expected = f"https://github.com/{repository}"
        if git("remote", "get-url", "origin") not in (expected, expected + ".git"):
            raise ValueError(
                "authenticated history fetch requires the exact GitHub origin"
            )
        fetch_env["HEPTA_UI_GIT_AUTH"] = (
            "AUTHORIZATION: basic "
            + base64.b64encode(f"x-access-token:{token}".encode()).decode()
        )
        command += [
            "-c",
            "http.followRedirects=false",
            "--config-env=http.https://github.com/.extraheader=HEPTA_UI_GIT_AUTH",
        ]
    command += ["fetch", "--no-tags", "--no-recurse-submodules"]
    if shallow_before:
        command.append("--unshallow")
    command += [
        "origin",
        f"+{base}:refs/hepta-ui-ci/base",
        f"+{source}:refs/hepta-ui-ci/source",
    ]
    subprocess.run(command, env=fetch_env, check=True)
    for revision in (base, source):
        if git("rev-parse", f"{revision}^{{commit}}") != revision:
            raise ValueError("fetched commit identity differs")
    if git("rev-parse", "--is-shallow-repository") != "false":
        raise ValueError("the immutable PR histories remain shallow")
    after = {
        "head": git("rev-parse", "HEAD"),
        "tree": git("rev-parse", "HEAD^{tree}"),
        "status": git("status", "--porcelain", "--untracked-files=normal"),
    }
    if after != before:
        raise ValueError("history fetch changed the source checkout")
    return {
        "schema": "hepta.ui-exact-history.v1",
        "base_sha": base,
        "source_sha": source,
        "source_tree": before["tree"],
        "shallow_before": shallow_before,
        "shallow_after": False,
        "checkout_unchanged": True,
        "requested_refs": ["refs/hepta-ui-ci/base", "refs/hepta-ui-ci/source"],
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--base", default=os.environ.get("HEPTA_UI_BASE_SHA"))
    parser.add_argument("--source", default=os.environ.get("HEPTA_UI_SOURCE_SHA"))
    parser.add_argument("--repository", default=os.environ.get("HEPTA_UI_REPOSITORY"))
    args = parser.parse_args()
    token = os.environ.pop("HEPTA_UI_CHECKOUT_TOKEN", "")
    print(json.dumps(fetch_history(args.base, args.source, args.repository, token)))


if __name__ == "__main__":
    main()

import hashlib
import json
import os
import subprocess
from pathlib import Path

out = Path(os.environ["RUNNER_TEMP"]) / "hepta-musl-product-smoke"
out.mkdir(exist_ok=True)
secret = os.environ.get("BUILDBUDDY_API_KEY", "").encode()
def digest(path):
    value = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            value.update(chunk)
    return value.hexdigest()

# BEP options/client environment can contain credentials. Retain only the
# event/metric projection below, never the raw options, command lines or environment.
raw_bep = Path(os.environ["RUNNER_TEMP"]) / "hepta-musl-product-build.bep.json"
projection = []
malformed_lines = 0
if raw_bep.exists():
    for line in raw_bep.read_text().splitlines():
        try:
            event = json.loads(line)
        except json.JSONDecodeError:
            malformed_lines += 1
            continue
        selected = {}
        if "started" in event:
            selected["started"] = {k: event["started"][k] for k in
                                  ("uuid", "buildToolVersion", "command") if k in event["started"]}
        if "finished" in event:
            selected["finished"] = {k: event["finished"][k] for k in
                                   ("overallSuccess", "exitCode") if k in event["finished"]}
        if "completed" in event:
            selected["target"] = event.get("id", {}).get("targetCompleted")
            selected["completed"] = {k: event["completed"][k] for k in
                                    ("success", "targetKind") if k in event["completed"]}
        if "buildMetrics" in event:
            selected["buildMetrics"] = {k: event["buildMetrics"][k] for k in
                                       ("actionSummary", "targetMetrics", "timingMetrics")
                                       if k in event["buildMetrics"]}
        if selected:
            projection.append(selected)
(out / "build-events-projection.json").write_text(json.dumps({
    "raw_bep_present": raw_bep.exists(), "malformed_lines": malformed_lines,
    "raw_bep_sha256": digest(raw_bep) if raw_bep.exists() else None,
    "raw_options_environment_and_command_lines_retained": False, "events": projection,
}, indent=2) + "\n")
# Redact the sole workflow-provided credential in textual logs before upload.
for path in out.rglob("*"):
    if path.is_file() and "binary" not in path.relative_to(out).parts:
        data = path.read_bytes()
        if secret:
            data = data.replace(secret, b"[REDACTED_BUILDBUDDY_API_KEY]")
        path.write_bytes(data)
source_path = out / "source.json"
source = json.loads(source_path.read_text()) if source_path.exists() else {}
head = subprocess.check_output(["git", "rev-parse", "HEAD"], text=True).strip()
tree = subprocess.check_output(["git", "rev-parse", "HEAD^{tree}"], text=True).strip()
changes = subprocess.check_output(
    ["git", "status", "--porcelain", "--untracked-files=no"], text=True).strip()
receipt_path = out / "receipt.json"
receipt = json.loads(receipt_path.read_text()) if receipt_path.exists() else {
    "status": "not_executed", "qualified": False,
}
receipt["terminal_source"] = {"checkout": head, "tree": tree, "tracked_changes": changes}
receipt["source_unchanged"] = head == source.get("checkout") and tree == source.get("tree") and not changes
binary = out / "binary" / "hepta"
receipt["terminal_product_sha256"] = digest(binary) if binary.is_file() else None
receipt["product_unchanged"] = (
    receipt["terminal_product_sha256"] is not None
    and receipt["terminal_product_sha256"] == receipt.get("product", {}).get("sha256"))
receipt["qualified"] = bool(receipt.get("qualified") and receipt["source_unchanged"]
                            and receipt["product_unchanged"])
receipt_path.write_text(json.dumps(receipt, indent=2) + "\n")
manifest = []
for path in sorted(out.rglob("*")):
    if path.is_file():
        manifest.append({"path": str(path.relative_to(out)),
                         "bytes": path.stat().st_size, "sha256": digest(path)})
(out / "artifact-manifest.json").write_text(json.dumps(manifest, indent=2) + "\n")

